package com.bank.emi.service;

import com.bank.emi.exception.PaymentGatewayException;
import com.bank.emi.model.EmiPayment;
import com.bank.emi.repository.EmiRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class BuggyEmiService {

    private final EmiRepository emiRepo;

    // ═══ PITFALL 1: CHECKED EXCEPTION — TX COMMITS instead of rolling back! ═══
    @Transactional  // only rolls back on RuntimeException/Error!
    public void processEmiPitfall1(String emiId) throws PaymentGatewayException {
        EmiPayment emi = emiRepo.findById(emiId).orElseThrow();
        emi.markProcessed();
        emiRepo.save(emi);

        // Simulate payment gateway failure (CHECKED exception)
        throw new PaymentGatewayException("Gateway timeout");
        // Proxy catches PaymentGatewayException (CHECKED) → does NOT rollback → COMMITS!
        // EMI is marked PROCESSED even though payment FAILED → DATA CORRUPTION!
    }

    // ═══ PITFALL 2: SELF-INVOCATION — no proxy, no transaction ═══
    public void processAllPitfall2() {
        List<EmiPayment> pending = emiRepo.findByStatus("PENDING");
        for (EmiPayment emi : pending) {
            this.processOnePitfall2(emi.getEmiId());  // ← SELF-INVOCATION!
            // "this." calls the REAL object directly, NOT through the proxy.
            // @Transactional is SILENTLY IGNORED. No transaction!
        }
    }

    @Transactional  // IGNORED because called via this.method() — proxy bypassed!
    public void processOnePitfall2(String emiId) {
        EmiPayment emi = emiRepo.findById(emiId).orElseThrow();
        emi.markProcessed();
        emiRepo.save(emi);
        log.warn("[PITFALL 2] @Transactional IGNORED — called via self-invocation!");
    }

    // ═══ PITFALL 3: PRIVATE METHOD — CGLIB cannot override ═══
    @Transactional  // SILENTLY IGNORED — CGLIB cannot override private!
    private void processEmiPitfall3(String emiId) {
        // This annotation does NOTHING. The method runs without a transaction.
        log.warn("[PITFALL 3] @Transactional on private method — IGNORED!");
    }

    // ═══ PITFALL 4: SWALLOWED EXCEPTION — proxy sees success, commits ═══
    @Transactional
    public void processEmiPitfall4(String emiId) {
        EmiPayment emi = emiRepo.findById(emiId).orElseThrow();
        emi.markProcessed();
        emiRepo.save(emi);

        try {
            // Simulate failure
            throw new RuntimeException("Payment failed!");
        } catch (Exception e) {
            log.error("Payment failed: {}", e.getMessage());
            // Exception SWALLOWED! Not re-thrown.
            // Proxy sees: method returned normally → COMMIT!
            // EMI is PROCESSED but payment FAILED → DATA CORRUPTION!
        }
    }
}
