// *** ALL 4 FIXES ***
package com.bank.emi.service;

import com.bank.emi.exception.PaymentGatewayException;
import com.bank.emi.model.EmiPayment;
import com.bank.emi.repository.EmiRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.interceptor.TransactionAspectSupport;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class FixedEmiService {

    private final EmiRepository emiRepo;
    private final EmiProcessorService emiProcessor;  // separate bean → no self-invocation

    // ═══ FIX 1: rollbackFor = Exception.class → checked exceptions also rollback ═══
    @Transactional(rollbackFor = Exception.class)  // ← FIX!
    public void processEmiFix1(String emiId) throws PaymentGatewayException {
        EmiPayment emi = emiRepo.findById(emiId).orElseThrow();
        emi.markProcessed();
        emiRepo.save(emi);

        throw new PaymentGatewayException("Gateway timeout");
        // Now proxy rolls back on PaymentGatewayException too → data safe!
    }

    // ═══ FIX 2: call SEPARATE bean → proxy intercepts → @Transactional works ═══
    public void processAllFix2() {
        List<EmiPayment> pending = emiRepo.findByStatus("PENDING");
        for (EmiPayment emi : pending) {
            emiProcessor.processOneEmi(emi.getEmiId());  // ← SEPARATE BEAN!
            // Call goes through EmiProcessorService proxy → @Transactional active!
        }
    }

    // ═══ FIX 3: make method PUBLIC → CGLIB can override ═══
    @Transactional(rollbackFor = Exception.class)
    public void processEmiFix3(String emiId) {  // ← PUBLIC, not private!
        EmiPayment emi = emiRepo.findById(emiId).orElseThrow();
        emi.markProcessed();
        emiRepo.save(emi);
        log.info("[FIX 3] Public method — @Transactional works correctly");
    }

    // ═══ FIX 4: re-throw exception OR setRollbackOnly ═══
    @Transactional(rollbackFor = Exception.class)
    public void processEmiFix4(String emiId) {
        EmiPayment emi = emiRepo.findById(emiId).orElseThrow();
        emi.markProcessed();
        emiRepo.save(emi);

        try {
            throw new RuntimeException("Payment failed!");
        } catch (Exception e) {
            log.error("Payment failed: {}", e.getMessage());
            // FIX Option A: re-throw
            // throw e;

            // FIX Option B: manual rollback (when you need to catch but still rollback)
            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
            log.info("[FIX 4] setRollbackOnly() — TX will rollback even though exception is caught");
        }
    }
}
